import itertools

def find_good_sequences(n):
    num_elements = n + 1
    def get_sums(target, length):
        if length == 1:
            yield (target,)
            return
        for i in range(target + 1):
            for rest in get_sums(target - i, length - 1):
                yield (i,) + rest

    results = []
    for a in get_sums(num_elements, num_elements):
        if any(x >= num_elements for x in a):
            continue
        b = [0] * num_elements
        for x in a:
            b[x] += 1

        match = True
        for k in range(num_elements):
            if b.count(k) != a[k]:
                match = False
                break
        if match:
            s = sum((i + 1) * (a[i]**2) for i in range(num_elements))
            results.append(s)
    return results

for n in range(1, 9):
    print(f"n={n}: {find_good_sequences(n)}")

def find_good_sequences_with_a(n):
    num_elements = n + 1
    good_sequences = []
    def get_partitions(target, max_val):
        if target == 0:
            yield {}
            return
        if max_val == 0:
            return
        for k in range(target // max_val, -1, -1):
            for rest in get_partitions(target - k * max_val, max_val - 1):
                res = rest.copy()
                res[max_val] = k
                yield res
    for part in get_partitions(num_elements, n):
        a_1 = num_elements - sum(k * part.get(k, 0) for k in range(2, n+1))
        if a_1 < 0: continue
        a_0 = sum((k-1) * part.get(k, 0) for k in range(2, n+1))
        a = [0] * num_elements
        a[0] = a_0
        a[1] = a_1
        for k in range(2, n+1):
            a[k] = part.get(k, 0)
        if sum(a) != num_elements: continue
        b = [0] * num_elements
        for x in a:
            if 0 <= x < num_elements: b[x] += 1
            else: break
        else:
            if all(b.count(k) == a[k] for k in range(num_elements)):
                good_sequences.append(a)
    return good_sequences

